 for(let i=0;i<text.length;i++){const char=text[i],next=text[i+1];if(char==='"'&&quoted&&next==='"'){field+='"';i++}else if(char==='"'){quoted=!quoted}else if(char===","&&!quoted){row.push(field.trim());field=""}else if((char==="\n"||char==="\r")&&!quoted){if(char==="\r"&&next==="\n")i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=""}else field+=char}
