 rows.forEach((row,index)=>{const email=primaryContactEmail(value(row,"email")),rawFull=value(row,"fullName"),full=rawFull.includes("@")?"":rawFull,parts=full.split(/\s+/).filter(Boolean);let first=value(row,"firstName")||parts[0]||"",last=value(row,"lastName")||parts.slice(1).join(" ")||"";const inferred=deriveNameFromEmail(email,first,last);first=inferred.first;last=inferred.last;if(inferred.derived)derived.push(index+2);if(!email||!first||!last){invalid.push(index+2);return}if(unique.has(email))duplicates.push(email);const opt=value(row,"subscribed").toLowerCase();unique.set(email,{firstName:first,lastName:last,email,company:value(row,"company"),title:value(row,"title"),phone:value(row,"phone"),location:value(row,"location"),stage:value(row,"stage")||"Lead",tags:value(row,"tags").split(/[;|]/).map(v=>v.trim()).filter(Boolean),subscribed:!["false","no","0","unsubscribed","optout"].includes(opt)})});
