function Dashboard({data,tasks,complete,activity,campaign}:{data:CRMData;tasks:Task[];complete:(id:number)=>void;activity:()=>void;campaign:()=>void}){return <><Heading eyebrow="Monday, September 21" title="Here’s who needs your attention" action={<Button variant="outline" onClick={activity}><MessageSquareText size={17}/>Record interaction</Button>}/><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Total contacts" value={data.contacts.length} detail={`${data.contacts.filter(c=>c.stage==="Customer").length} active customers`} icon={Users}/><Metric label="Open follow-ups" value={tasks.length} detail="Stay ahead of commitments" icon={CalendarClock}/><Metric label="Needs attention" value={data.contacts.filter(c=>c.lastContact&&c.lastContact<"2026-09-01").length} detail="No contact in 30+ days" icon={Mail}/><Metric label="Subscribed" value={data.contacts.filter(c=>c.subscribed).length} detail="Available for campaigns" icon={Send}/></div><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Panel><div className="border-b p-5"><h2 className="font-semibold">Follow-ups</h2><p className="mt-1 text-sm text-slate-500">The next actions already promised.</p></div>{tasks.map(t=><div key={t.id} className="flex items-center gap-4 border-b p-5 last:border-0"><button onClick={()=>complete(t.id)} className="grid h-8 w-8 place-items-center rounded-full border-2 text-transparent hover:border-[#3968ff] hover:text-[#3968ff]"><Check size={15}/></button><div className="flex-1"><div className="font-medium">{t.title}</div><div className="text-sm text-slate-500">{t.contactName}</div></div><div className={`text-sm font-medium ${t.dueDate<="2026-09-21"?"text-[#d44c3f]":"text-slate-500"}`}>{t.dueDate==="2026-09-21"?"Today":t.dueDate}</div></div>)}</Panel><Panel><div className="border-b p-5"><h2 className="font-semibold">Recent conversations</h2></div>{data.activities.slice(0,3).map(a=><div key={a.id} className="border-b p-5 last:border-0"><div className="flex items-center"><strong>{a.contactName}</strong><span className="ml-auto text-xs text-slate-400">{a.type}</span></div><p className="mt-2 text-sm leading-6 text-slate-600">{a.note}</p></div>)}</Panel></div><Panel className="mt-6 overflow-hidden"><div className="bg-[#111b31] p-6 text-white md:flex md:items-end md:justify-between"><div><div className="mb-6 text-sm font-medium text-[#95a9d4]">Campaign workspace</div><h2 className="max-w-xl text-2xl font-semibold">Reach the right customers without rebuilding your list.</h2><p className="mt-3 max-w-xl text-sm leading-6 text-slate-300">Create the audience, draft the message, and review every recipient before delivery.</p></div><Button onClick={campaign} className="mt-6 bg-white text-[#111b31] hover:bg-slate-100 md:mt-0">Create campaign draft</Button></div></Panel></>}
